package docker

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"
)

// IsBuildCacheID checks the full base36 ID generated by BuildKit.
func IsBuildCacheID(id string) bool {
	return len(id) == 25 && strings.IndexFunc(id, func(r rune) bool {
		return (r < 'a' || r > 'z') && (r < '0' || r > '9')
	}) == -1
}

// ExactCacheRemoval allows the Docker Engine releases whose Moby bridge
// forwards id~= to BuildKit's cache matcher. Verified in builder/builder-next/
// builder.go and vendor/github.com/moby/buildkit/cache/manager.go at v27.3.1
// and v28.5.2. An API version alone says nothing about the daemon's filters.
func (c *Client) ExactCacheRemoval() bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	return !older(c.version, "1.47") && c.platform == "Docker Engine - Community" &&
		(c.engine == "27.3.1" || c.engine == "28.5.2")
}

// BuildCacheCutoff is the last-use limit sent with a reviewed prune.
func BuildCacheCutoff(lastUsed *time.Time) time.Time {
	if lastUsed != nil {
		return *lastUsed
	}
	return time.Unix(1, 0).UTC()
}

// RemoveBuildCache requests GC for exactly one BuildKit cache record. BuildKit
// excludes records in use again inside its cache manager.
func (c *Client) RemoveBuildCache(ctx context.Context, id string, lastUsed *time.Time) ([]string, error) {
	if !c.ExactCacheRemoval() || !IsBuildCacheID(id) {
		return nil, errors.New("this Engine cannot target the exact cache record")
	}
	cutoff := BuildCacheCutoff(lastUsed)
	filters, err := json.Marshal(map[string]map[string]bool{
		"id":    {"^" + regexp.QuoteMeta(id) + "$": true},
		"until": {cutoff.Format(time.RFC3339Nano): true},
	})
	if err != nil {
		return nil, err
	}
	var out struct{ CachesDeleted []string }
	if err := c.boundedJSON(ctx, http.MethodPost, "/build/prune", url.Values{"filters": {string(filters)}}, &out); err != nil {
		return nil, err
	}
	return out.CachesDeleted, nil
}
